19	import net.officefloor.hq.app.claim.ClaimStatus;
20	import net.officefloor.hq.app.person.Person;
21	import net.officefloor.hq.app.person.PersonHold;
22	import net.officefloor.hq.app.person.PersonRepository;
23	import net.officefloor.hq.app.person.PersonService;
24	import net.officefloor.hq.app.setting.Permission;
25	import net.officefloor.hq.app.setting.SettingService;
26	import net.officefloor.hq.app.sheet.SheetService;
27	import org.springframework.stereotype.Service;
28	import org.springframework.transaction.annotation.Transactional;
29	
30	/** The periods on a sheet: named date ranges, no two overlapping. */
31	@Service
32	public class PeriodService {
33	
34	    private final PeriodRepository periods;
35	    private final SheetService sheets;
36	    private final ClaimRepository claims;
37	    private final ClaimService claimService;
38	    private final PersonRepository people;
39	    private final PersonService personService;
40	    private final SettingService settings;
41	    private final History history;
42	    private final Audit audit;
43	
44	    public PeriodService(PeriodRepository periods, SheetService sheets, ClaimRepository claims,
45	            ClaimService claimService, PersonRepository people, PersonService personService, SettingService settings,
46	            History history, Audit audit) {
47	        this.history = history;
48	        this.periods = periods;
49	        this.sheets = sheets;
50	        this.claims = claims;
51	        this.claimService = claimService;
52	        this.people = people;
53	        this.personService = personService;
54	        this.settings = settings;
55	        this.audit = audit;
56	    }
57	
58	    /** The sheet's periods, the earliest first. */
59	    public List<Period> list(String sheetId) {
60	        return periods.findBySheetIdOrderByFromAsc(sheetId);
61	    }
62	
63	    /** The sheet's periods as they stood at the end of a day, the earliest first: those added by then,
64	     *  each closed, soft-closed or open as it was then. */
65	    public List<History.PeriodThen> listAsOf(String sheetId, LocalDate day) {
66	        return history.periods(sheetId, day).values().stream()
67	                .sorted(Comparator.comparing(History.PeriodThen::from)).toList();
68	    }
69	
70	    /** Save a period, keeping the state it is saved in with the sheet's today. */
71	    private Period save(Period period) {
72	        Period saved = periods.saveAndFlush(period);
73	        history.periodSaved(saved.getId(), saved.getSheetId(), saved.getName(), saved.getFrom(), saved.getTo(),
74	                saved.isClosed(), saved.isSoftClosed(), saved.getClosedTotal(), saved.getPersonTotals(),
75	                saved.getPersonCarried());
76	        return saved;
77	    }
78	
79	    /** Add a period from and to a date, inclusive, capping each person's OPEN and PENDING claims in
80	     *  it (null: no cap). Refused when the cap is below 1, when another period on the sheet has the
81	     *  name, the from-date is after the to-date, or it shares a day with another period. The sheet
82	     *  is held locked so periods added at the same moment are checked against each other. */
83	    @Transactional
84	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
85	        sheets.lock(sheetId);
86	        if (cap != null && cap < 1) {
87	            throw new PeriodRefusedException("The period's cap is not a whole number of at least 1");
88	        }
89	        if (from.isAfter(to)) {
90	            throw new PeriodRefusedException("The period's from-date is after its to-date");
91	        }
92	        if (periods.nameInUse(sheetId, name)) {
93	            throw new PeriodRefusedException("The name " + name + " is already in use on the sheet");
94	        }
95	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
96	            throw new PeriodRefusedException("The period overlaps another on the sheet");
97	        }
98	        Period saved = save(new Period(sheetId, name, from, to, cap));
99	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + name
100	                + " from=" + from + " to=" + to + (cap != null ? " cap=" + cap : ""));
101	        return saved;
102	    }
103	
104	    /** Generate one period per calendar month from the from-date's month to the to-date's month,
105	     *  each running from the first to the last day of its month and named yyyy-mm; a blank date is
106	     *  the sheet's today. A month whose name is already a period, or whose days overlap a period on
107	     *  the sheet, is left out and the others are still made. Refused when the to-date is before the
108	     *  from-date. Returns how many were made. */
109	    @Transactional
110	    public int generate(String sheetId, String user, LocalDate from, LocalDate to) {
111	        sheets.lock(sheetId);
112	        LocalDate today = sheets.today(sheetId);
113	        LocalDate start = from != null ? from : today;
114	        LocalDate end = to != null ? to : today;
115	        if (end.isBefore(start)) {
116	            throw new PeriodRefusedException("The to-date is before the from-date");
117	        }
118	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
119	        int made = 0;
120	        for (YearMonth month = YearMonth.from(start); !month.isAfter(YearMonth.from(end)); month = month.plusMonths(1)) {
121	            String name = month.toString();
122	            LocalDate first = month.atDay(1);
123	            LocalDate last = month.atEndOfMonth();
124	            if (periods.nameInUse(sheetId, name) || existing.stream().anyMatch(p -> p.overlaps(first, last))) {
125	                continue;
126	            }
127	            Period saved = save(new Period(sheetId, name, first, last));
128	            existing.add(saved);
129	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + name
130	                    + " from=" + first + " to=" + last);
131	            made++;
132	        }
133	        return made;
134	    }
135	
136	    /** Generate the twelve monthly periods of fiscal year FY<year>, the one whose first day is the first
137	     *  of the sheet's fiscal year start month in that year, exactly as {@link #generate} does. Returns
138	     *  how many were made. */
139	    @Transactional
140	    public int generateFiscalYear(String sheetId, String user, int year) {
141	        LocalDate first = LocalDate.of(year, settings.fiscalStartMonth(sheetId), 1);
142	        return generate(sheetId, user, first, first.plusMonths(11));
143	    }
144	
145	    /** Close a period (one soft-closed too, fixing its figures afresh), fixing each person's due-total for it, for everyone on the sheet, and its own
146	     *  due-total, their sum: the figures shown on the claims due by a day in it that counted at the end of its last day (by the
147	     *  status each had then, as its status log records it)
148	     *  (a claim with no figure adds nothing; an OPEN claim dated within its person's hold and not bound by a statement counts for nothing). A period already closed, or a close by a role the sheet's permission matrix does not allow, is refused. */
149	    @Transactional
150	    public Period close(String sheetId, String user, String name) {
151	        sheets.lock(sheetId);
152	        Period period = periods.findBySheetIdAndName(sheetId, name)
153	                .orElseThrow(() -> new NoSuchElementException("No period " + name + " on sheet " + sheetId));
154	        if (!settings.allows(sheetId, user, Permission.CLOSE)) {
155	            throw new PeriodRefusedException("Your role may not close the period " + name);
156	        }
157	        if (period.isClosed()) {
158	            throw new PeriodClosedException("The period " + name + " is already closed");
159	        }
160	        return closeFixing(sheetId, user, period, "");
161	    }
162	
163	    /** Close, as a close by hand would, every open period (not closed or soft-closed) whose to-date plus the sheet's grace days is
164	     *  before the sheet's today, in order of their to-dates, each recorded with auto=yes; nothing when
165	     *  the grace days are blank (off). The sheet's permission matrix governs a close by hand, not this
166	     *  one. Made when the sheet's today is changed, after it is set. */
167	    @Transactional
168	    public void autoClose(String sheetId, String user) {
169	        sheets.lock(sheetId);
170	        Integer grace = settings.graceDays(sheetId);
171	        if (grace == null) {
172	            return;
173	        }
174	        LocalDate today = sheets.today(sheetId);
175	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
176	                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getTo().plusDays(grace).isBefore(today))
177	                .sorted(Comparator.comparing(Period::getTo))
178	                .forEach(p -> closeFixing(sheetId, user, p, " auto=yes"));
179	    }
180	
181	    /** Soft-close a period, fixing each person's due-total for it and its own due-total as a close
182	     *  would, while claims dated in it can still be added and changed. A period already closed or
183	     *  soft-closed, or a soft close by a role the sheet's permission matrix does not allow to close,
184	     *  is refused. */
185	    @Transactional
186	    public Period softClose(String sheetId, String user, String name) {
187	        sheets.lock(sheetId);
188	        Period period = periods.findBySheetIdAndName(sheetId, name)
189	                .orElseThrow(() -> new NoSuchElementException("No period " + name + " on sheet " + sheetId));
190	        if (!settings.allows(sheetId, user, Permission.CLOSE)) {
191	            throw new PeriodRefusedException("Your role may not close the period " + name);
192	        }
193	        if (period.isClosed() || period.isSoftClosed()) {
194	            throw new PeriodClosedException("The period " + name + " is already closed");
195	        }
196	        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period);
197	        BigDecimal total = sum(personTotals);
198	        period.softClose(total, personTotals, personCarried(sheetId, period));
199	        Period saved = save(period);
200	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + name
201	                + " total=" + total.toPlainString());
202	        return saved;
203	    }
204	
205	    private Period closeFixing(String sheetId, String user, Period period, String suffix) {
206	        String name = period.getName();
207	        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period);
208	        BigDecimal total = sum(personTotals);
209	        period.close(total, personTotals, personCarried(sheetId, period));
210	        Period saved = save(period);
211	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + name
212	                + " total=" + total.toPlainString() + suffix);
213	        return saved;
214	    }
215	
216	    private static BigDecimal sum(Map<Long, BigDecimal> personTotals) {
217	        return personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
218	    }
219	
220	    /** Each person's due-total for the period now, by person id, everyone on the sheet. */
221	    private Map<Long, BigDecimal> personTotals(String sheetId, Period period) {
222	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
223	                .collect(Collectors.toMap(Person::getId, Function.identity()));
224	        Map<Long, List<PersonHold>> holds = personService.holds(sheetId);
225	        LocalDate today = sheets.today(sheetId);
226	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
227	        byId.keySet().forEach(id -> personTotals.put(id, BigDecimal.ZERO.setScale(2)));
228	        Map<Long, ClaimStatus> atEnd = claimService.statusesAsOf(sheetId, period.getTo());
229	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
230	            Person person = byId.get(claim.getPersonId());
231	            if (person == null
232	                    || !claim.countsAsOf(atEnd.get(claim.getId()), holds.getOrDefault(person.getId(), List.of()),
233	                            person.getRetiredFrom(), today)
234	                    || !period.contains(claim.getDueBy())) {
235	                continue;
236	            }
237	            BigDecimal due = claimService.dueOf(sheetId, person, claim);
238	            if (due != null) {
239	                personTotals.merge(person.getId(), due, BigDecimal::add);
240	            }
241	        }
242	        return personTotals;
243	    }
244	
245	    /** Each person's carried figure for the period now, by person id, everyone on the sheet: the dues
246	     *  shown now on their claims whose due-by falls in a period ending before this one starts, that
247	     *  were still OPEN or PENDING at the end of this period's last day (by the status each had then, as
248	     *  its status log records it) and the live rules leave in (a claim with no figure adds nothing), and
249	     *  their opening balance for it. */
250	    private Map<Long, BigDecimal> personCarried(String sheetId, Period period) {
251	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
252	                .collect(Collectors.toMap(Person::getId, Function.identity()));
253	        Map<Long, List<PersonHold>> holds = personService.holds(sheetId);
254	        List<Period> all = periods.findBySheetIdOrderByFromAsc(sheetId);
255	        LocalDate today = sheets.today(sheetId);
256	        Map<Long, BigDecimal> carried = new LinkedHashMap<>();
257	        byId.keySet().forEach(id -> carried.put(id, BigDecimal.ZERO.setScale(2)));
258	        period.getPersonOpenings().forEach((id, amount) -> carried.computeIfPresent(id, (key, sum) -> sum.add(amount)));
259	        Map<Long, ClaimStatus> atEnd = claimService.statusesAsOf(sheetId, period.getTo());
260	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
261	            Person person = byId.get(claim.getPersonId());
262	            ClaimStatus then = atEnd.get(claim.getId());
263	            if (person == null || then == null || !then.isOpen()
264	                    || !claim.countsAsOf(then, holds.getOrDefault(person.getId(), List.of()),
265	                            person.getRetiredFrom(), today)
266	                    || all.stream().noneMatch(own -> own.contains(claim.getDueBy())
267	                            && own.getTo().isBefore(period.getFrom()))) {
268	                continue;
269	            }
270	            BigDecimal due = claimService.dueOf(sheetId, person, claim);
271	            if (due != null) {
272	                carried.merge(person.getId(), due, BigDecimal::add);
273	            }
274	        }
275	        return carried;
276	    }
277	
278	    /** A pasted opening balance, read: the person and period it names and its amount. */
279	    private record Opening(Person person, Period period, BigDecimal amount) {
280	    }
281	
282	    /** Add each pasted line of name,period,amount to that person's opening balance for that period, in
283	     *  the order of the lines: a person on the sheet by name or alias, a period on the sheet by name, and
284	     *  an amount of 0.00 or more with up to two decimals; blank lines are skipped. Every line is checked
285	     *  first: one refused line, or none at all, changes nothing. How many lines went through. */
286	    @Transactional
287	    public int importOpenings(String sheetId, String user, String text) {
288	        sheets.lock(sheetId);
289	        List<Opening> lines = new ArrayList<>();
290	        int at = 0;
291	        for (String raw : text.split("\\r?\\n")) {
292	            at++;
293	            if (!raw.isBlank()) {
294	                lines.add(readOpening(sheetId, at, raw));
295	            }
296	        }
297	        if (lines.isEmpty()) {
298	            throw new OpeningRefusedException("Nothing to import");
299	        }
300	        for (Opening line : lines) {
301	            line.period().addOpening(line.person().getId(), line.amount());
302	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + line.person().getName()
303	                    + " period=" + line.period().getName() + " amount=" + line.amount().toPlainString());
304	        }
305	        lines.stream().map(Opening::period).distinct().forEach(periods::saveAndFlush);
306	        return lines.size();
307	    }
308	
309	    private Opening readOpening(String sheetId, int at, String raw) {
310	        String[] fields = raw.split(",", -1);
311	        if (fields.length != 3) {
312	            throw new OpeningRefusedException("Line " + at + " needs name,period,amount");
313	        }
314	        String name = fields[0].trim();
315	        Person person = name.isEmpty() ? null : people.findByName(sheetId, name).orElse(null);
316	        if (person == null) {
317	            throw new OpeningRefusedException("Line " + at + ": no person " + name + " on the sheet");
318	        }
319	        Period period = periods.findBySheetIdAndName(sheetId, fields[1].trim())
320	                .orElseThrow(() -> new OpeningRefusedException("Line " + at + ": no period " + fields[1].trim()));
321	        String amount = fields[2].trim();
322	        if (!amount.matches("\\d{1,10}(\\.\\d{1,2})?")) {
323	            throw new OpeningRefusedException("Line " + at + ": the amount must be 0.00 or more, with up to two decimals");
324	        }
325	        return new Opening(person, period, new BigDecimal(amount).setScale(2));
326	    }
327	
328	    /** Reopen a closed or soft-closed period, making its due-total live again. Only a role the sheet's
329	     *  permission matrix allows may (by the standing rule a steward); a period that is not closed is refused. */
330	    @Transactional
331	    public Period reopen(String sheetId, String user, String name) {
332	        sheets.lock(sheetId);
333	        Period period = periods.findBySheetIdAndName(sheetId, name)
334	                .orElseThrow(() -> new NoSuchElementException("No period " + name + " on sheet " + sheetId));
335	        if (!settings.allows(sheetId, user, Permission.REOPEN)) {
336	            throw new PeriodRefusedException("Your role may not reopen the period " + name);
337	        }
338	        if (!period.isClosed() && !period.isSoftClosed()) {
339	            throw new PeriodRefusedException("The period " + name + " is not closed");
340	        }
341	        period.reopen();
342	        Period saved = save(period);
343	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + name);
344	        return saved;
345	    }
346	}
